int vc4_prepare_cmdlist_and_shaders(struct drm_device *dev, struct vc4_exec_info *exec)
{
    int ret;
    void *cmdlist, *shader_records;
    struct vc4_bo *bo;

    if (!exec->cmdlist_size || !exec->shader_records_size) {
        return -EINVAL;
    }

    cmdlist = kvmalloc(exec->cmdlist_size, GFP_KERNEL);
    if (!cmdlist) {
        return -ENOMEM;
    }

    shader_records = kvmalloc(exec->shader_records_size, GFP_KERNEL);
    if (!shader_records) {
        kvfree(cmdlist);
        return -ENOMEM;
    }

    if (copy_from_user(cmdlist, u64_to_user_ptr(exec->cmdlist), exec->cmdlist_size)) {
        ret = -EFAULT;
        goto fail_cmdlist;
    }

    if (copy_from_user(shader_records, u64_to_user_ptr(exec->shader_records), exec->shader_records_size)) {
        ret = -EFAULT;
        goto fail_shader_records;
    }

    bo = vc4_bo_create(dev, exec->cmdlist_size + exec->shader_records_size, 0);
    if (IS_ERR(bo)) {
        ret = PTR_ERR(bo);
        goto fail_bo;
    }

    exec->bo = bo;
    exec->cmdlist = cmdlist;
    exec->shader_records = shader_records;

    ret = vc4_validate_command_list(cmdlist, exec->cmdlist_size);
    if (ret) {
        goto fail_validate;
    }

    ret = vc4_setup_shader_records_pointers(exec, shader_records);
    if (ret) {
        goto fail_validate;
    }

    vc4_wait_for_rendering_complete(dev);

    return 0;

fail_validate:
    vc4_bo_unreference(exec->bo);
fail_bo:
fail_shader_records:
    kvfree(shader_records);
fail_cmdlist:
    kvfree(cmdlist);
    return ret;
}

int vc4_prepare_cmdlists_and_shaders(struct drm_device *dev, struct vc4_exec_info *exec)
{
    void *cmdlist_data, *shader_records_data;
    int ret;

    if (!exec->cmdlist_size || !exec->shader_records_size)
        return -EINVAL;

    cmdlist_data = kvmalloc(exec->cmdlist_size);
    if (!cmdlist_data)
        return -ENOMEM;

    shader_records_data = kvmalloc(exec->shader_records_size);
    if (!shader_records_data) {
        ret = -ENOMEM;
        goto err_free_cmdlist;
    }

    if (!access_ok(VERIFY_READ, (void __user *)exec->cmdlist_ptr, exec->cmdlist_size) ||
        !access_ok(VERIFY_READ, (void __user *)exec->shader_records_ptr, exec->shader_records_size)) {
        ret = -EFAULT;
        goto err_free_shader_records;
    }

    if (copy_from_user(cmdlist_data, (void __user *)exec->cmdlist_ptr, exec->cmdlist_size)) {
        ret = -EFAULT;
        goto err_free_shader_records;
    }

    if (copy_from_user(shader_records_data, (void __user *)exec->shader_records_ptr, exec->shader_records_size)) {
        ret = -EFAULT;
        goto err_free_shader_records;
    }

    exec->cmdlist = cmdlist_data;
    exec->shader_records = shader_records_data;

    ret = vc4_validate_cmdlist_and_shaders(dev, exec);
    if (ret)
        goto err_cleanup;

    ret = vc4_wait_for_rendering_completion(dev, exec);
    if (ret)
        goto err_cleanup;

    return 0;

err_cleanup:
    kvfree(exec->cmdlist);
    kvfree(exec->shader_records);
err_free_shader_records:
    kvfree(shader_records_data);
err_free_cmdlist:
    kvfree(cmdlist_data);
    return ret;
}

int vc4_get_cmdlist_and_shader_records(struct drm_device *dev, struct vc4_exec_info *exec)
{
    int ret;
    unsigned int i;
    struct vc4_bo *bo;

    if (!exec->cmdlist_size || !exec->shader_record_size) {
        return -EINVAL;
    }

    exec->cmdlist = kmalloc(exec->cmdlist_size, GFP_KERNEL);
    if (!exec->cmdlist) {
        return -ENOMEM;
    }

    ret = copy_from_user(exec->cmdlist, u64_to_user_ptr(exec->cmdlist_ptr), exec->cmdlist_size);
    if (ret) {
        ret = -EFAULT;
        goto fail;
    }

    exec->shader_records = kmalloc(exec->shader_record_size, GFP_KERNEL);
    if (!exec->shader_records) {
        ret = -ENOMEM;
        goto fail;
    }

    ret = copy_from_user(exec->shader_records, u64_to_user_ptr(exec->shader_record_ptr), exec->shader_record_size);
    if (ret) {
        ret = -EFAULT;
        goto fail;
    }

    ret = vc4_validate_cmdlist(exec->cmdlist, exec->cmdlist_size);
    if (ret)
        goto fail;

    for (i = 0; i < exec->num_shader_records; i++) {
        struct vc4_shader_record *record = &exec->shader_records[i];

        if (!record->size) {
            ret = -EINVAL;
            goto fail;
        }

        record->data = kmemdup(record->data_ptr, record->size, GFP_KERNEL);
        if (!record->data) {
            ret = -ENOMEM;
            goto fail;
        }
    }

    bo = vc4_bo_create(dev, exec->cmdlist_size, ttm_bo_type_kernel, false);
    if (IS_ERR(bo)) {
        ret = PTR_ERR(bo);
        goto fail;
    }

    exec->cmdlist_bo = bo;

    ret = vc4_bo_map(bo);
    if (ret)
        goto fail;

    memcpy(bo->vaddr, exec->cmdlist, exec->cmdlist_size);

    ret = vc4_wait_for_previous_rendering_complete(dev);
    if (ret)
        goto fail;

    return 0;

fail:
    if (exec->cmdlist)
        kfree(exec->cmdlist);
    if (exec->shader_records)
        kfree(exec->shader_records);
    for (i = 0; i < exec->num_shader_records; i++) {
        struct vc4_shader_record *record = &exec->shader_records[i];
        if (record->data)
            kfree(record->data);
    }

    return ret;
}

int vc4_prepare_cmdlists_and_shaders(struct drm_device *dev, struct vc4_exec_info *exec)
{
    int ret;
    struct vc4_dev *vdev = dev->dev_private;
    struct vc4_bo *bo = NULL;
    void *cmdlists, *shaders;
    size_t cmdlist_size, shader_size;

    if (!exec->cmdlist_size || !exec->shader_size)
        return -EINVAL;

    cmdlist_size = exec->cmdlist_size;
    shader_size = exec->shader_size;

    cmdlists = kzalloc(cmdlist_size, GFP_KERNEL);
    if (!cmdlists)
        return -ENOMEM;

    shaders = kzalloc(shader_size, GFP_KERNEL);
    if (!shaders) {
        ret = -ENOMEM;
        goto fail_shaders_alloc;
    }

    if (copy_from_user(cmdlists, u64_to_user_ptr(exec->cmdlist_ptr), cmdlist_size)) {
        ret = -EFAULT;
        goto fail_copy_cmdlists;
    }

    if (copy_from_user(shaders, u64_to_user_ptr(exec->shader_ptr), shader_size)) {
        ret = -EFAULT;
        goto fail_copy_shaders;
    }

    bo = vc4_bo_create(dev, cmdlist_size + shader_size, 0, ttm_bo_type_kernel, NULL);
    if (IS_ERR(bo)) {
        ret = PTR_ERR(bo);
        bo = NULL;
        goto fail_bo_create;
    }

    ret = vc4_bo_map(bo);
    if (ret)
        goto fail_bo_map;

    memcpy(bo->vma->vmapping, cmdlists, cmdlist_size);
    memcpy(bo->vma->vmapping + cmdlist_size, shaders, shader_size);

    exec->bo = bo;

    ret = vc4_check_cmdlist_validity(cmdlists, cmdlist_size);
    if (ret)
        goto fail_cmdlist_check;

    ret = vc4_setup_shader_records(exec, shaders, shader_size);
    if (ret)
        goto fail_shader_setup;

    ret = vc4_wait_for_render_complete(vdev);
    if (ret)
        goto fail_wait;

    return 0;

fail_wait:
fail_shader_setup:
fail_cmdlist_check:
    vc4_free_shader_resources(exec);
fail_bo_map:
    vc4_bo_unmap(bo);
fail_bo_create:
    vc4_bo_unref(&bo);
fail_copy_shaders:
    kfree(shaders);
fail_copy_cmdlists:
    kfree(cmdlists);
fail_shaders_alloc:
    return ret;
}

int vc4_prepare_cmdlists_and_shaders(struct drm_device *dev, struct vc4_exec_info *exec)
{
    void *cmdlist_ptr, *shader_records_ptr;
    int ret = 0;

    if (exec->cmdlist_size == 0 || exec->shader_records_size == 0) {
        return -EINVAL;
    }

    cmdlist_ptr = kzalloc(exec->cmdlist_size, GFP_KERNEL);
    if (!cmdlist_ptr) {
        return -ENOMEM;
    }

    shader_records_ptr = kzalloc(exec->shader_records_size, GFP_KERNEL);
    if (!shader_records_ptr) {
        ret = -ENOMEM;
        goto fail_free_cmdlist;
    }

    if (copy_from_user(cmdlist_ptr, u64_to_user_ptr(exec->cmdlist_addr), exec->cmdlist_size) != 0) {
        ret = -EFAULT;
        goto fail_free_shader_records;
    }

    if (copy_from_user(shader_records_ptr, u64_to_user_ptr(exec->shader_records_addr), exec->shader_records_size) != 0) {
        ret = -EFAULT;
        goto fail_free_shader_records;
    }

    exec->cmdlist = cmdlist_ptr;
    exec->shader_records = shader_records_ptr;

    ret = vc4_validate_cmdlist(exec);
    if (ret) {
        goto fail_free_shader_records;
    }

    ret = vc4_validate_shader_records(exec);
    if (ret) {
        goto fail_free_shader_records;
    }

    exec->bo = vc4_bo_create(dev, exec->cmdlist_size + exec->shader_records_size, 0);
    if (!exec->bo) {
        ret = -ENOMEM;
        goto fail_free_shader_records;
    }

    if (exec->bo->size < exec->cmdlist_size + exec->shader_records_size) {
        ret = -ENOMEM;
        goto fail_unref_bo;
    }

    exec->cmdlist_gpu_addr = exec->bo->dma_addr;
    exec->shader_records_gpu_addr = exec->cmdlist_gpu_addr + exec->cmdlist_size;

    if (exec->bo->vma) {
        dma_sync_single_for_device(dev->dev, exec->bo->dma_addr, exec->bo->size, DMA_TO_DEVICE);
    }

    if (exec->previous_fence) {
        wait_for_completion_interruptible(&exec->previous_fence->completion);
    }

    return 0;

fail_unref_bo:
    drm_gem_object_put_unlocked(&exec->bo->base);
fail_free_shader_records:
    kfree(shader_records_ptr);
fail_free_cmdlist:
    kfree(cmdlist_ptr);
    return ret;
}
